#define SHADER "#include <metal_stdlib>\nusing namespace metal;\nstruct V{float4 p [[position]];};\nvertex V vert(uint i [[vertex_id]]){float2 p=float2((i<<1)&2,i&2);return {float4(p*2-1,0,1)};}\nfloat2 rot(float2 p,float a){return float2(cos(a)*p.x-sin(a)*p.y,sin(a)*p.x+cos(a)*p.y);}\nfloat3 palette(float x){float v=.5+.5*cos(6.28318*x);return float3(v);}\nfragment float4 frag(V v [[stage_in]],constant float3 &u [[buffer(0)]]){\n float t=u.z;float2 uv=(v.p.xy*2-u.xy)/u.y;float beat=exp(-5*fract(t*2));\n float3 c=0;float scene=floor(t/24);float fade=smoothstep(0.,2.,t)*(1-smoothstep(92.,96.,t));\n if(scene<1){\n float2 p=rot(uv,t*.22);float glow=0.;\n for(int i=0;i<7;i++){\n  float f=float(i);float phase=t*(.39+f*.027)+f*2.399;\n  float radius=.042+.0015*f;\n  float orbit=.25+.025*sin(t*.17+f*1.31);\n  float2 center=float2(cos(phase),.78*sin(phase*1.07+f*.4))*orbit;\n  float2 push=float2(0);float impact=0.;\n  for(int j=0;j<7;j++)if(j!=i){\n   float g=float(j),otherPhase=t*(.39+g*.027)+g*2.399;\n   float otherOrbit=.25+.025*sin(t*.17+g*1.31);\n   float2 other=float2(cos(otherPhase),.78*sin(otherPhase*1.07+g*.4))*otherOrbit;\n   float2 delta=center-other;float dist=length(delta);\n   float hit=1.-smoothstep(.055,.13,dist);\n   impact=max(impact,hit);\n   push+=normalize(delta+float2(.0001,.0002))*hit;\n  }\n  center+=normalize(push+float2(.0001,.0002))*impact*.09;\n  float2 q=rot((p-center)/radius,t*(.42+f*.025)+f*.71);\n  float sector=6.2831853/3.;float folded=abs(fract(atan2(q.y,q.x)/sector+.5)-.5)*sector;\n  float edge=abs(length(q)*cos(folded)-.72);\n  float tri=.005/(edge+.005);\n  float3 ink=palette(f*.06);\n  c+=ink*tri*(.55+impact*3.2+.35*cos(f*1.7+t*.24));\n  glow+=exp(-length(p-center)*(7.+impact*12.))*(.004+impact*.075);\n }\n c+=glow;\n }else if(scene<2){\n float2 p=rot(uv,.12*sin(t*.19));float r=length(p),a=atan2(p.y,p.x);\n float spin=t*.035;\n float oct=6.2831853/8.;float folded=abs(fract((a+spin)/oct+.5)-.5)*oct;\n float starR=r*cos(folded);\n float pulse=.025*sin(t*.23);\n float outer=abs(starR-(.62+pulse));\n float inner=abs(starR-(.40-pulse*.6));\n float ring1=abs(r-(.72+.018*sin(a*8.+t*.16)));\n float ring2=abs(r-(.25+.015*cos(a*8.-t*.13)));\n float rails=abs(sin((a+spin)*8.))*.018;\n float lines=.009/(outer+.009)+.007/(inner+.007);\n float rings=.005/(ring1+.005)+.006/(ring2+.006);\n float spokes=.0035/(rails+.0035)*step(.28,r)*step(r,.73);\n float gate=step(.5,fract((a*8.+t*.018)*.5));\n c=float3(lines*.58+rings*.45+spokes*.17*(.3+.7*gate));\n float core=exp(-r*12.);c+=core*.12;\n }else if(scene<3){\n float2 drift=float2(.28*sin(t*.31),.19*sin(t*.23+1.1));float2 qv=uv-drift;float3 ro=float3(0,0,-3.6),rd=normalize(float3(qv,1.6));float travel=0;\n for(int i=0;i<64;i++){float3 p=ro+rd*travel;p.xz=rot(p.xz,t*.21);p.yz=rot(p.yz,t*.16);float3 q=p;\n for(int j=0;j<3;j++){q=abs(q)-float3(.63,.48,.52);q.xy=rot(q.xy,.6+.15*sin(t*.2));q.xz=rot(q.xz,.8);}\n float d=(length(q)-.23)/3.;float edge=exp(-abs(d)*115.);float shade=exp(-abs(d)*27.);c+=palette(length(p)*.16+t*.018)*(.35*edge+.065*shade)*exp(-travel*.24);travel+=max(abs(d)*.82,.012);if(travel>7)break;\n }\n }else{\n float2 p=rot(uv,t*.19);for(int i=0;i<11;i++){float f=float(i);float2 q=p;q.y+=.20*sin(q.x*3.2+t*1.35+f*.8)+.055*sin(q.x*9.-t*2.1+f*1.7)+.024*sin(q.x*19.+t*2.8-f);float d=abs(q.y-(f-5)*.135);float vib=.008+.004*sin(t*3.2+f);c+=palette(f*.08+q.x*.12+t*.06)*(vib*.42)/(d+.008);p=rot(p,.13+.025*sin(t*1.4+f));}\n }\n fade*=smoothstep(0.,.6,fmod(t,24.))*(1-smoothstep(23.4,24.,fmod(t,24.)));\n float grain=fract(sin(dot(v.p.xy,float2(12.9898,78.233)))*43758.5453);\n c=1-exp(-c*2.2);c*=max(0.,1-.18*dot(uv,uv));c=pow(max(c,0.),float3(.62));c=smoothstep(.08,.62,c);c=(c+(grain-.5)*.018)*fade;\n return float4(c,1);\n}\n"
